


/* ── 자동완성 엔진 (단순·확실 버전) ── */

// ═══════════════════════════════════════════════════════════
// CGo-Fuli 주소 검색 엔진 v3.0
// ① 초성 검색  ② 동명 지자체 구분  ③ Datalist 비동기  ④ OSM 폴백
// ═══════════════════════════════════════════════════════════

// ── 초성 테이블 ──────────────────────────────────────────────
var _CHOSUNG = ['ㄱ','ㄲ','ㄴ','ㄷ','ㄸ','ㄹ','ㅁ','ㅂ','ㅃ','ㅅ','ㅆ','ㅇ','ㅈ','ㅉ','ㅊ','ㅋ','ㅌ','ㅍ','ㅎ'];
function _getChosung(str) {
  return str.split('').map(function(ch) {
    var code = ch.charCodeAt(0) - 0xAC00;
    if (code < 0 || code > 11171) return ch;
    return _CHOSUNG[Math.floor(code / 588)];
  }).join('');
}
function _matchChosung(query, target) {
  // 쿼리가 초성만으로 구성됐는지 체크
  var isAllChosung = query.split('').every(function(c){ return _CHOSUNG.indexOf(c) > -1; });
  if (!isAllChosung) return target.toLowerCase().indexOf(query.toLowerCase()) > -1;
  return _getChosung(target).indexOf(query) > -1;
}

// ── 동명 중복 지자체 구분 DB ────────────────────────────────
// 같은 이름의 동/읍/면이 여러 지역에 있을 때 지자체명으로 구분
var _DONG_AMBIGUOUS = {
  '전미동':  ['군산 전미동','전주 전미동'],
  '신사동':  ['강남구 신사동','마포구 신사동'],
  '중앙동':  ['군산 중앙동','춘천 중앙동','원주 중앙동','강릉 중앙동','속초 중앙동'],
  '성내동':  ['강동구 성내동','고창 성내면'],
  '남면':    ['태안 남면','부여 남면(부여)','서천 서면(서천)'],
  '서면':    ['울산 서면','창원 서면'],
  '동면':    ['창원 동면','진주 동면'],
  '대야면':  ['군산 대야면','시흥 대야동'],
  '회현면':  ['군산 회현면','서울 회현동'],
  '성산면':  ['군산 성산면','창원 성산구'],
  '남양면':  ['화성 남양읍','청양 남양면'],
  '광시면':  ['예산 광시면'],
  '고산면':  ['완주 고산면','홍성 고산'],
  '안성면':  ['무주 안성면','죽산면'],
  '신평면':  ['임실 신평면','당진 신평면'],
  '강진면':  ['임실 강진면','전남 강진군'],
  '구림면':  ['순창 구림면','영암 군서면'],
};

// ── 지자체 컨텍스트 분석 ────────────────────────────────────
// "군산 전미동" 입력 시 지자체(군산)를 먼저 파악해서 해당 동만 우선 표시
function _parseContext(query) {
  var q = query.trim();
  // 지자체명 앞부분 분리 시도 (예: "군산 전미" → {city:"군산", dong:"전미"})
  var CITIES_KR = ['서울','부산','인천','대구','광주','대전','울산','세종',
    '수원','고양','성남','용인','부천','안산','화성','남양주','김포','파주',
    '의정부','군산','전주','익산','정읍','남원','김제','완주','고창','부안',
    '순창','진안','무주','장수','임실','청주','충주','제천','천안','아산',
    '당진','보령','서산','논산','홍성','예산','청양','부여','태안','서천',
    '포항','경주','구미','안동','경산','창원','진주','김해','거제','양산',
    '춘천','원주','강릉','속초','동해','태백','삼척','제주','서귀포'];
  var foundCity = '';
  var foundDong = q;
  // "전주시 전미동" → "전주시"도 "전주"로 인식
  var qNorm = q.replace(/시\s/,'시 ').replace(/군\s/,'군 ');
  CITIES_KR.forEach(function(city) {
    // 정확 매칭: "전주 " 또는 "전주시 "
    var patterns = [city + ' ', city + '시 ', city + '군 ', city + '구 '];
    patterns.forEach(function(pat) {
      if (q.indexOf(pat) === 0) {
        foundCity = city;
        foundDong = q.slice(pat.length).trim();
      }
    });
    // 공백 없이 붙은 경우: "전주전미동"
    if (!foundCity && q.indexOf(city) === 0 && q.length > city.length) {
      foundCity = city;
      foundDong = q.slice(city.length).trim();
    }
  });
  return { city: foundCity, dong: foundDong, raw: q };
}

// ── 내장DB 초성+동명지자체 통합 검색 ───────────────────────
function _ipSearchLocal(query) {
  if (typeof _CITIES === 'undefined') return [];
  var ctx = _parseContext(query);
  var q   = ctx.dong || ctx.raw;
  var results = [];
  var seen = {};

  _CITIES.forEach(function(c) {
    var score = 0;
    var matched = false;
    var displayCity = ''; // 동명 지자체 구분용

    // ① 지자체 컨텍스트 매칭 (최고 우선순위)
    if (ctx.city && c.n.toLowerCase().indexOf(ctx.city.toLowerCase()) > -1) {
      if (_matchChosung(q, c.n)) { score = 100; matched = true; }
    }
    // ② 초성/일반 매칭
    if (!matched && _matchChosung(query, c.n)) {
      score = c.n.toLowerCase().indexOf(query.toLowerCase()) === 0 ? 80 : 50;
      matched = true;
    }

    if (!matched) return;
    if (seen[c.n + '|' + c.lat]) return;
    seen[c.n + '|' + c.lat] = true;

    // ③ 동명 중복 지자체 구분 라벨 생성
    var isDup = false;
    Object.keys(_DONG_AMBIGUOUS).forEach(function(k) {
      if (c.n.indexOf(k) > -1 || k === c.n) isDup = true;
    });

    // 지자체명 추출 (예: "군산 전미동" → "군산")
    var parts = c.n.match(/^([가-힣]+[시군구]|서울|부산|인천|대구|광주|대전|울산|세종|군산|전주|익산|정읍|청주|천안|창원|수원|고양|성남)\s(.+)$/);
    if (parts) displayCity = parts[1];
    else if (isDup) {
      // 괄호 안 지자체명 추출
      var m = c.n.match(/\(([^)]+)\)/);
      if (m) displayCity = m[1];
    }

    var isDong = c.n.indexOf('동')>-1||c.n.indexOf('읍')>-1||c.n.indexOf('면')>-1||c.n.indexOf('리')>-1;
    results.push({
      n: c.n,
      addr: displayCity,
      lat: c.lat,
      lng: c.lng,
      isDong: isDong,
      score: score,
      isDup: isDup
    });
  });

  results.sort(function(a,b){ return b.score - a.score; });
  return results.slice(0, 15);
}

// ── 메인 자동완성 함수 ───────────────────────────────────────
function ipAutoSuggest(val, type) {
  var drop = document.getElementById(type==='birth' ? 'ipBirthDrop' : 'ipCurDrop');
  if (!drop) return;
  var v = val.trim();
  if (v.length < 1) { drop.style.display='none'; return; }

  // ── 현재 검색어 스냅샷 저장 (비동기 응답 시 비교용) ──────
  drop._lastQuery = v;

  // ── 즉시: 내장DB 초성 검색 (0ms 반응) ──────────────────
  var localResults = _ipSearchLocal(v);
  if (localResults.length) _ipRenderDrop(localResults, type, drop);

  // ── OSM 호출 여부 판단 ───────────────────────────────────
  // 아래 조건 중 하나라도 해당하면 OSM 호출 완전 차단
  var ctx2 = _parseContext(v);
  var skipOSM = false;

  // 조건1: 지자체 + 동 조합 입력 ("전주 전미동", "군산 전미동" 등)
  if (ctx2.city !== '') skipOSM = true;

  // 조건2: 내장DB에 높은 점수(직접 매칭) 결과가 있음
  if (localResults.length > 0 && localResults[0].score >= 80) skipOSM = true;

  // 조건3: 쿼리가 동/읍/면/리 로 끝남 → 내장DB로 충분
  if (/[동읍면리]$/.test(v)) skipOSM = true;

  // 조건4: 내장DB 결과가 3개 이상 → 충분한 결과
  if (localResults.length >= 3) skipOSM = true;

  if (skipOSM) {
    clearTimeout(window._ipSuggestTimer);
    return;
  }

  // ── 비동기: OSM Nominatim (내장DB 결과 없을 때만) ────────
  clearTimeout(window._ipSuggestTimer);
  window._ipSuggestTimer = setTimeout(function(){
    // 검색어가 바뀌었으면 무시
    if (drop._lastQuery !== v) return;

    var url = 'https://nominatim.openstreetmap.org/search'
      + '?q=' + encodeURIComponent(v)
      + '&format=json&addressdetails=1&limit=8&accept-language=ko&countrycodes=kr';
    fetch(url, { headers:{'User-Agent':'CGo-Fuli/1.0'} })
    .then(function(r){ return r.json(); })
    .then(function(data){
      // 응답 받은 시점에 검색어가 바뀌었으면 무시 (핵심!)
      if (drop._lastQuery !== v) return;
      if (!data || !data.length) return;

      var seen = {};
      var osmItems = data.map(function(d){
        var a = d.address || {};
        var nm = a.quarter||a.suburb||a.neighbourhood||a.village||a.hamlet
               ||a.town||a.city_district||a.city||d.display_name.split(',')[0];
        var city  = a.city||a.county||a.city_district||'';
        var state = a.state||'';
        var addr  = [city, state].filter(Boolean).join(' ');
        var isDong = !!(a.quarter||a.suburb||a.neighbourhood||a.village||a.hamlet);
        return { n:nm.trim(), addr:addr, lat:parseFloat(d.lat), lng:parseFloat(d.lon),
                 isDong:isDong, score:40, isDup:false, fromOSM:true };
      }).filter(function(d){
        if (!d.n || isNaN(d.lat)) return false;
        if (seen[d.n]) return false;
        seen[d.n] = true; return true;
      });
      if (!osmItems.length) return;

      // 내장DB 결과가 다시 생겼으면 OSM 무시
      var freshLocal = _ipSearchLocal(v);
      if (freshLocal.length >= 2) return;

      // 내장DB + OSM 병합 (내장DB 완전 우선)
      var merged = freshLocal.slice();
      var localNames = freshLocal.map(function(r){ return r.n; });
      osmItems.forEach(function(o){
        if (localNames.indexOf(o.n) === -1) merged.push(o);
      });
      _ipRenderDrop(merged.slice(0,12), type, drop);
    })
    .catch(function(){}); // 실패해도 내장DB 결과 유지
  }, 600);
}

// ── 드롭다운 렌더링 (동명 지자체 배지 포함) ─────────────────
function _ipRenderDrop(items, type, drop) {
  if (!items.length) { drop.style.display='none'; return; }
  drop.innerHTML = '';
  items.forEach(function(c) {
    var row = document.createElement('div');
    row.style.cssText = 'padding:9px 14px;border-bottom:1px solid rgba(255,255,255,.05);cursor:pointer;transition:background .1s';

    // 동 단위 정밀 배지
    var precBadge = c.isDong
      ? '<span style="font-size:9px;background:rgba(52,211,153,.15);color:#34d399;border-radius:4px;padding:1px 5px;margin-left:4px">동 단위 ✓</span>'
      : '';
    // OSM 출처 배지
    var osmBadge = c.fromOSM
      ? '<span style="font-size:9px;background:rgba(56,189,248,.1);color:#38bdf8;border-radius:4px;padding:1px 4px;margin-left:3px">OSM</span>'
      : '';
    // 동명 중복 → 지자체 구분 배지 (핵심!)
    var cityBadge = c.addr
      ? '<span style="font-size:10px;color:#94a3b8;margin-left:5px;font-weight:400">[' + c.addr + ']</span>'
      : '';
    // 중복 경고 배지
    var dupBadge = c.isDup
      ? '<span style="font-size:9px;background:rgba(251,191,36,.1);color:#fbbf24;border-radius:4px;padding:1px 4px;margin-left:3px">동명 다수</span>'
      : '';

    var coord = '<span style="font-size:9px;color:rgba(148,163,184,.4);flex-shrink:0">'
              + c.lat.toFixed(4)+'°N '+c.lng.toFixed(4)+'°E</span>';

    row.innerHTML = '<div style="display:flex;align-items:center;justify-content:space-between;gap:6px">'
      + '<span style="font-size:13px;font-weight:700;color:#f1f5f9;flex:1;min-width:0">'
      + c.n + cityBadge + precBadge + osmBadge + dupBadge + '</span>'
      + coord + '</div>';

    row.onmouseover = function(){ this.style.background='rgba(56,189,248,.08)'; };
    row.onmouseout  = function(){ this.style.background=''; };
    (function(city, t){
      // PC 클릭
      row.onclick = function(e){
        e.preventDefault(); e.stopPropagation();
        ipSaveCity(t, city.n, city.lat, city.lng);
      };
      // 모바일 터치
      row.addEventListener('touchend', function(e){
        e.preventDefault(); e.stopPropagation();
        ipSaveCity(t, city.n, city.lat, city.lng);
      }, {passive: false});
      // 포인터 이벤트 (터치+펜+마우스 통합)
      row.addEventListener('pointerdown', function(e){
        e.preventDefault(); e.stopPropagation();
        ipSaveCity(t, city.n, city.lat, city.lng);
      }, {passive: false});
    })(c, type);
    drop.appendChild(row);
  });
  drop.style.display = 'block';
}

// ── 폴백 함수 (하위호환 유지) ─────────────────────────────
function _ipSuggestFallback(v, type, drop) {
  var r = _ipSearchLocal(v);
  if (r.length) _ipRenderDrop(r, type, drop);
  else drop.style.display = 'none';
}

function ipSaveCity(type, name, lat, lng) {
  lat = parseFloat(lat);
  lng = parseFloat(lng);
  if (isNaN(lat) || isNaN(lng)) return;

  if (type === 'birth') {
    document.getElementById('ipBirthLat').value = lat;
    document.getElementById('ipBirthLng').value = lng;
    document.getElementById('ipBirthPlace').value = name + ' (' + lat.toFixed(3) + '°N ' + lng.toFixed(3) + '°E)';
    window._selectedBirthLat = lat;
    window._selectedBirthLng = lng;
  } else {
    document.getElementById('ipCurLat').value = lat;
    document.getElementById('ipCurLng').value = lng;
    document.getElementById('ipCurPlace').value = name + ' (' + lat.toFixed(3) + '°N ' + lng.toFixed(3) + '°E)';
    window._selectedCurLat = lat;
    window._selectedCurLng = lng;
  }

  // 드롭다운 닫기
  var dropId = type === 'birth' ? 'ipBirthDrop' : 'ipCurDrop';
  var drop = document.getElementById(dropId);
  if (drop) drop.style.display = 'none';

  // X 버튼 표시
  var cl = document.getElementById(type === 'birth' ? 'ipBirthClear' : 'ipCurClear');
  if (cl) cl.style.display = 'inline-block';

  // 초록 테두리 피드백
  var inp = document.getElementById(type === 'birth' ? 'ipBirthPlace' : 'ipCurPlace');
  if (inp) {
    inp.style.borderColor = '#34d399';
    inp.style.boxShadow = '0 0 0 2px rgba(52,211,153,.25)';
    setTimeout(function(){ inp.style.borderColor=''; inp.style.boxShadow=''; }, 1500);
  }
}

function ipPickCity(type, name, lat, lng) { ipSaveCity(type, name, lat, lng); }

function ipClearPlace(type) {
  var inpId  = type==='birth' ? 'ipBirthPlace' : 'ipCurPlace';
  var latId  = type==='birth' ? 'ipBirthLat'   : 'ipCurLat';
  var lngId  = type==='birth' ? 'ipBirthLng'   : 'ipCurLng';
  var dropId = type==='birth' ? 'ipBirthDrop'  : 'ipCurDrop';
  var clId   = type==='birth' ? 'ipBirthClear' : 'ipCurClear';
  var inp = document.getElementById(inpId);
  if(inp){ inp.value=''; inp.style.borderColor=''; inp.focus(); }
  document.getElementById(latId).value = '';
  document.getElementById(lngId).value = '';
  if(type==='birth'){ window._selectedBirthLat=0; window._selectedBirthLng=0; }
  else { window._selectedCurLat=0; window._selectedCurLng=0; }
  document.getElementById(dropId).style.display = 'none';
  var cl = document.getElementById(clId); if(cl) cl.style.display='none';
}

document.addEventListener('mousedown', function(e){
  ['ipBirthDrop','ipCurDrop'].forEach(function(id){
    var d = document.getElementById(id);
    if(d && d.style.display!=='none') {
      var inp = document.getElementById(id==='ipBirthDrop'?'ipBirthPlace':'ipCurPlace');
      // 드롭다운 내부 클릭이면 닫지 않음
      if(!d.contains(e.target) && e.target !== inp) d.style.display='none';
    }
  });
});


