// ── AI 검색 응답 캐시 ─────────────────────────────────────
var STK_AI_CACHE = {};

// ── 오행 정보 ─────────────────────────────────────────────
var STK_ELEM = [
  {label:'금(金)',emoji:'⚙️',color:'#94a3b8'},
  {label:'수(水)',emoji:'💧',color:'#60a5fa'},
  {label:'목(木)',emoji:'🌳',color:'#059669'},
  {label:'화(火)',emoji:'🔥',color:'#f87171'},
  {label:'토(土)',emoji:'🪨',color:'#d97706'},
];

// ── 현재 선택 기업 ────────────────────────────────────────
var stkSelected = null;
var _stkLiveTimer = null;

// ── 오행 계산 (천간 기반) ──────────────────────────────────
function stkGetElement(dateStr) {
  if (!dateStr) return null;
  var y = new Date(dateStr).getFullYear();
  var ei = [2,2,3,3,4,4,0,0,1,1][y % 10];
  return Object.assign({idx:ei}, STK_ELEM[ei]);
}

// ── DB 검색 ────────────────────────────────────────────────
function stkDBSearch(q) {
  q = q.toLowerCase().trim();
  return STK_DB.filter(function(c){
    return c.n.toLowerCase().indexOf(q) !== -1 || c.t.toLowerCase().indexOf(q) !== -1;
  }).slice(0, 8);
}

// ── 타이핑 시 드롭다운 ─────────────────────────────────────
var _stkSearchTimer = null;
function stkSearchInput(val) {
  var dd = document.getElementById('stk-dropdown');
  if (!val || val.length < 1) { dd.style.display = 'none'; return; }
  clearTimeout(_stkSearchTimer);

  var matches = stkDBSearch(val);
  if (matches.length > 0) {
    // DB 히트: 즉시 드롭다운
    stkRenderDropdown(matches, false);
  } else {
    // DB 미스: 0.6초 후 AI 검색 힌트 표시
    dd.innerHTML = '<div style="padding:12px 14px;font-size:12px;color:#a78bfa;display:flex;align-items:center;gap:8px;">'
      + '<span style="animation:spin 0.8s linear infinite;display:inline-block;">🤖</span>'
      + 'DB에 없는 기업 · AI가 검색합니다...</div>';
    dd.style.display = 'block';
    _stkSearchTimer = setTimeout(function(){ stkAISearch(val); }, 600);
  }
}

// ── 드롭다운 렌더 ─────────────────────────────────────────
function stkRenderDropdown(list, fromAI) {
  var dd = document.getElementById('stk-dropdown');
  if (!list.length) { dd.style.display = 'none'; return; }
  dd.innerHTML = (fromAI ? '<div style="padding:5px 14px;font-size:10px;color:#a78bfa;border-bottom:1px solid rgba(139,92,246,0.15);">🤖 AI 검색 결과</div>' : '')
    + list.map(function(c) {
    var ei = c.ei !== undefined ? c.ei : (stkGetElement(c.f) ? stkGetElement(c.f).idx : 3);
    var eInfo = STK_ELEM[ei] || STK_ELEM[3] || {label:'',emoji:'🌐',color:'#94a3b8'};
    return '<div onclick="stkPickItem('+JSON.stringify(c).replace(/"/g,'&quot;')+')"'
      + ' style="padding:10px 14px;cursor:pointer;display:flex;align-items:center;gap:10px;border-bottom:1px solid rgba(255,255,255,0.04);transition:background .12s;"'
      + ' onmouseover="this.style.background=\'rgba(139,92,246,0.12)\'" onmouseout="this.style.background=\'\'"> '
      + '<span style="font-size:15px;">'+(c.c||'🌐')+'</span>'
      + '<span style="font-size:13px;font-weight:600;color:#334155;flex:1;">'+c.n+'</span>'
      + '<span style="font-size:11px;color:#60a5fa;min-width:52px;">'+(c.t||'')+'</span>'
      + '<span style="font-size:13px;">'+eInfo.emoji+'</span>'
      + '<span style="font-size:10px;color:var(--text-3);">'+(c.s||'')+'</span>'
      + '</div>';
  }).join('');
  dd.style.display = 'block';
}

// ── AI에게 설립일 물어보기 (Groq 재활용) ──────────────────
function stkAISearch(companyName) {
  // 캐시 확인
  if (STK_AI_CACHE[companyName]) {
    stkRenderDropdown([STK_AI_CACHE[companyName]], true);
    return;
  }

  var apiKey = (window.CG_GEMINI_KEY || '').trim();
  if (!apiKey) {
    var dd = document.getElementById('stk-dropdown');
    dd.innerHTML = '<div style="padding:12px 14px;font-size:12px;color:#f87171;">⚠️ API 키 필요 — ⚙️ 버튼에서 입력해주세요<br><span style="color:var(--text-3);font-size:10px;">API 키 없이는 내장 DB('+STK_DB.length+'개 기업)만 검색됩니다</span></div>';
    return;
  }

  var spin = document.getElementById('stk-search-spin');
  if (spin) spin.style.display = 'block';

  var prompt = '기업명: "' + companyName + '"\n\n'
    + '이 기업의 정보를 JSON으로만 답하세요. 다른 설명 없이 JSON만:\n'
    + '{"name":"정확한기업명","ticker":"종목코드또는N/A","founded":"YYYY-MM-DD","country":"국가ISO2코드","sector":"주요업종한국어"}\n\n'
    + '설립일은 법인 설립 또는 공식 창업일 기준. 정확히 모르면 연도만이라도 YYYY-01-01로.'
    + '반드시 JSON 하나만, 마크다운 없이.';

  fetch('/api/groq', {
    method: 'POST',
    headers: {'Content-Type':'application/json'},
    body: JSON.stringify({
      model: 'openai/gpt-oss-20b',reasoning_effort:'low',include_reasoning:false,
      messages: [{role:'user', content: prompt}],
      max_tokens: 200,
      temperature: 0.1
    })
  })
  .then(function(r){ return r.json(); })
  .then(function(data) {
    if (spin) spin.style.display = 'none';
    var text = (data.choices && data.choices[0] && data.choices[0].message && data.choices[0].message.content) || '';
    // JSON 파싱
    var jsonMatch = text.match(/\{[\s\S]*?\}/);
    if (!jsonMatch) throw new Error('파싱실패');
    var info = JSON.parse(jsonMatch[0]);

    // 국가 이모지 변환
    var flagMap = {'KR':'🇰🇷','US':'🇺🇸','JP':'🇯🇵','CN':'🇨🇳','TW':'🇹🇼','DE':'🇩🇪','FR':'🇫🇷','NL':'🇳🇱','GB':'🇬🇧','IN':'🇮🇳','CA':'🇨🇦','AU':'🇦🇺'};
    var flag = flagMap[(info.country||'').toUpperCase()] || '🌐';
    var el = stkGetElement(info.founded);
    var ei = el ? el.idx : 3;

    var result = {
      n: info.name || companyName,
      t: info.ticker || 'N/A',
      f: info.founded || new Date().toISOString().slice(0,10),
      c: flag,
      s: info.sector || '기타',
      ei: ei,
      _aiFound: true
    };

    // 캐시 저장
    STK_AI_CACHE[companyName] = result;
    stkRenderDropdown([result], true);
  })
  .catch(function(e) {
    if (spin) spin.style.display = 'none';
    var dd = document.getElementById('stk-dropdown');
    dd.innerHTML = '<div style="padding:12px 14px;font-size:12px;color:#f87171;">AI 검색 실패: '+e.message+'</div>';
  });
}

// ── 드롭다운 항목 선택 ─────────────────────────────────────
function stkPickItem(obj) {
  stkSelected = obj;
  document.getElementById('stk-search').value = obj.n;
  document.getElementById('stk-dropdown').style.display = 'none';
  stkShowSelectedChip(obj);
}

// ── 선택 정보 칩 표시 ─────────────────────────────────────
// ── 실시간 시세 연동 (Twelve Data via /api/stock) C-build ──
var STK_KR_TICKERS = {'삼성전자':'005930','SK하이닉스':'000660','현대차':'005380','기아':'000270','카카오':'035720','네이버':'035420','NAVER':'035420','LG에너지솔루션':'373220','삼성바이오로직스':'207940','삼성SDI':'006400','삼성전기':'009150','삼성생명':'032830','삼성물산':'028260','POSCO홀딩스':'005490','포스코':'005490','셀트리온':'068270','KB금융':'105560','신한지주':'055550','하나금융지주':'086790','현대모비스':'012330','LG화학':'051910','SK이노베이션':'096770','한화에어로스페이스':'012450','두산에너빌리티':'034020','HD현대중공업':'329180','한화오션':'042660','크래프톤':'259960','카카오뱅크':'323410','SK스퀘어':'402340','기아차':'000270'};
var STK_COUNTRY_CODES = {'KR':1,'US':1,'JP':1,'CN':1,'TW':1,'DE':1,'FR':1,'NL':1,'GB':1,'IN':1,'CA':1,'AU':1,'HK':1,'SG':1,'UK':1,'한국':1,'해외':1,'기타':1,'home':1,'symbol':1,'shape':1,'':1};
function stkResolveSymbol(obj){
  var t=(obj.t||'').trim();
  if(t && !STK_COUNTRY_CODES[t] && /^[A-Za-z0-9][A-Za-z0-9.\-]{0,11}$/.test(t)) return {symbol:t, kr:/^\d{6}$/.test(t)};
  if(STK_KR_TICKERS[obj.n]) return {symbol:STK_KR_TICKERS[obj.n], kr:true};
  return null;
}
function stkFetchNews(obj){
  var box=document.getElementById('stk-news-weather'); if(!box) return;
  if(!obj || !obj.n){ box.style.display='none'; return; }
  var cc=''; try{ if(obj.c && typeof _stkFlagCode==='function') cc=_stkFlagCode(obj.c); }catch(e){}
  var LG={KR:['ko','KR'],US:['en','US'],JP:['ja','JP'],CN:['zh','CN'],GB:['en','GB'],DE:['de','DE'],FR:['fr','FR'],IT:['it','IT'],ES:['es','ES'],BR:['pt','BR'],IN:['en','IN'],ID:['id','ID'],NL:['nl','NL'],CA:['en','CA'],AU:['en','AU'],SE:['sv','SE'],NO:['no','NO']};
  var lg=LG[cc]||['en','US'];
  box.style.display='block';
  box.innerHTML='<div style="font-size:11px;color:#334155;">🌐 뉴스 기운 분석 중...</div>';
  fetch('/api/news?q='+encodeURIComponent(obj.n)+'&lang='+lg[0]+'&gl='+lg[1])
    .then(function(r){return r.json();})
    .then(function(d){
      if(!d || !d.ok){ box.style.display='block'; box.innerHTML='<div style=\"font-size:10.5px;color:#64748b;line-height:1.5;\">📰 실시간 뉴스를 불러오지 못했습니다.<br>(네트워크 또는 /api/news 응답 없음 · 잠시 후 자동 재시도)</div>'; return; }
      var heads='';
      (d.headlines||[]).forEach(function(h){
        var ttl=(h.title||'').replace(/</g,'&lt;');
        heads+='<a href="'+(h.link||'#')+'" target="_blank" rel="noopener" style="display:block;font-size:10.5px;color:#334155;text-decoration:none;margin-top:4px;line-height:1.45;border-left:2px solid rgba(255,255,255,0.12);padding-left:7px;">• '+ttl+(h.source?' <span style=\'color:rgba(150,170,190,0.6);\'>('+h.source+')</span>':'')+'</a>';
      });
      var _newsDate=window._stkDate(new Date(), true); box.innerHTML='<div style="display:flex;align-items:center;gap:8px;">'
        +'<span style="font-size:22px;">'+d.weather+'</span>'
        +'<div><div style="font-size:12.5px;font-weight:800;color:'+d.color+';">'+_newsDate+' '+(window._stkL()?'news energy':'뉴스 기운')+': '+window._stkTr('weather',d.weatherLabel)+' · '+((typeof _cgoT==='function')?_cgoT(d.element):d.element)+'</div>'
        +'<div style="font-size:10.5px;color:#334155;margin-top:1px;">'+d.message+'</div></div></div>'
        +(heads?'<div style="margin-top:7px;">'+heads+'</div>':'')
        +'<div style="font-size:9px;color:rgba(150,165,180,0.55);margin-top:6px;">⚠️ '+(d.disclaimer||'뉴스 기운은 참고용이며 투자 권유가 아닙니다.')+'</div>';
    })
    .catch(function(){ box.style.display='block'; box.innerHTML='<div style=\"font-size:10.5px;color:#64748b;line-height:1.5;\">📰 실시간 뉴스를 불러오지 못했습니다.<br>(네트워크 또는 /api/news 응답 없음 · 잠시 후 자동 재시도)</div>'; });
}
function stkFetchPrice(obj){
  var box=document.getElementById('stk-live-price');
  if(!box) return;
  var sym=stkResolveSymbol(obj);
  if(!sym){ box.style.display='block'; box.innerHTML='<span style=\"font-size:10.5px;color:#64748b;line-height:1.5;\">📋 이 종목은 실시간 시세 미지원입니다 — 종목코드(티커)가 등록되지 않았습니다. <b style=\"color:#334155\">사주 궁합 분석</b>은 정상 제공됩니다.</span>'; return; }
  box.style.display='block';
  box.innerHTML='<span style="font-size:11px;color:#334155">💰 현재가 불러오는 중…</span>';
  var _cc=''; try{ if(obj.c && typeof _stkFlagCode==='function') _cc=_stkFlagCode(obj.c); }catch(e){} if(!_cc && sym.kr) _cc='KR';
  fetch('/api/stock?symbol='+encodeURIComponent(sym.symbol)+'&cc='+encodeURIComponent(_cc))
    .then(function(r){return r.json();})
    .then(function(d){
      if(!d||!d.ok||d.price==null){ box.style.display='block'; box.innerHTML='<span style=\"font-size:10.5px;color:#64748b;\">💰 실시간 시세를 불러오지 못했습니다 (네트워크 또는 /api/stock 응답 없음)</span>'; return; }
      var _cur=(d.currency||'USD').toUpperCase();
      var _noDec={KRW:1,JPY:1,IDR:1,CLP:1,HUF:1,TWD:1};
      var _sufCur={KRW:'원',SEK:' kr',NOK:' kr',DKK:' kr',CZK:' Kč',PLN:' zł'};
      var _preCur={USD:'$',CAD:'C$',AUD:'A$',NZD:'NZ$',HKD:'HK$',SGD:'S$',TWD:'NT$',JPY:'¥',CNY:'¥',EUR:'€',GBP:'£',INR:'₹',BRL:'R$',CHF:'CHF ',ZAR:'R',MXN:'$',ILS:'₪',TRY:'₺',THB:'฿',RUB:'₽',IDR:'Rp ',MYR:'RM ',SAR:'﷼ ',AED:'AED '};
      var _amt=_noDec[_cur]?Math.round(d.price).toLocaleString():Number(d.price).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2});
      var priceStr=_sufCur[_cur]?(_amt+_sufCur[_cur]):((_preCur[_cur]||(_cur+' '))+_amt);
      var pct=(d.percent!=null&&isFinite(d.percent))?Number(d.percent):null;
      var up=pct!=null&&pct>=0;
      var arrow=pct==null?'':(up?'▲':'▼');
      var col=pct==null?'#94a3b8':(up?'#34d399':'#f87171');
      box.innerHTML='<div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap;">'
        +'<span style="font-size:14px;font-weight:800;color:#334155;">💰 '+priceStr+'</span>'
        +(pct!=null?'<span style="font-size:12px;font-weight:700;color:'+col+';">'+arrow+' '+Math.abs(pct).toFixed(2)+'%</span>':'')
        +'<span style="font-size:9px;color:#64748b;margin-left:auto;">'+(d.exchange||'')+' · 참고용</span>'
        +'</div>'
        +'<div style="font-size:9px;color:#64748b;margin-top:3px;">⚠️ 시세는 정보 제공용(지연 가능)이며, 실제 투자 판단은 본인 책임입니다.</div>';
    })
    .catch(function(){ if(box){ box.style.display='block'; box.innerHTML='<span style=\"font-size:10.5px;color:#64748b;\">💰 실시간 시세를 불러오지 못했습니다 (네트워크 또는 /api/stock 응답 없음)</span>'; } });
}
