// ── Enter / Esc 키 처리 ────────────────────────────────────
function stkSearchKey(e) {
  if (e.key === 'Enter') {
    var val = document.getElementById('stk-search').value.trim();
    var dd = document.getElementById('stk-dropdown');
    var first = dd.querySelector('[onclick]');
    if (first) { first.click(); }
    else { runStockAnalysis(); }
  }
  if (e.key === 'Escape') { document.getElementById('stk-dropdown').style.display = 'none'; }
}

// ── CSI 신버전: 5클러스터 상충·상쇄 지수 (txt 설계 v2.0) ──
// CGO-FULI 이주원 대장님 × Claude × Gemini 3인 합의 알고리즘
function stkCompat(e1, e2) {
  var ss = [[2,3],[3,4],[4,0],[0,1],[1,2]]; // 상생
  var sg = [[2,4],[4,1],[1,3],[3,0],[0,2]]; // 상극
  var now = new Date();

  // ━━ 클러스터 A: 동양시간역학 (기준) ━━
  // 사주명리·자미두수·기문둔갑·태을신수·구성기학·육임
  var aScore, aRel, aMsg;
  if (e1===e2){aScore=80;aRel='동행(同行)';aMsg='같은 오행! 에너지 공명이 강합니다. 상승·하락 모두 증폭됩니다.';}
  else if(ss.some(function(p){return p[0]===e1&&p[1]===e2;})){aScore=88;aRel='아생피(我生彼)';aMsg='나의 오행이 종목을 生합니다. 투자 에너지가 자연스럽게 흐릅니다.';}
  else if(ss.some(function(p){return p[0]===e2&&p[1]===e1;})){aScore=78;aRel='피생아(彼生我)';aMsg='종목이 나의 오행을 生합니다. 종목 에너지가 나에게 유리하게 작용합니다.';}
  else if(sg.some(function(p){return p[0]===e1&&p[1]===e2;})){aScore=52;aRel='아극피(我剋彼)';aMsg='나의 오행이 종목을 剋합니다. 단기 트레이딩엔 유리, 장기 보유 에너지 충돌 주의.';}
  else{aScore=45;aRel='피극아(彼剋我)';aMsg='종목이 나의 오행을 剋합니다. 소규모 포지션, 손절 기준 명확히.';}

  // ━━ 클러스터 B: 서양점성역학 ━━
  // 헬레니즘·베딕점성술·나크샤트라 — 행성 역행 여부 반영
  var bScore = 60;
  try {
    var pl = stkCalcPlanets();
    // 오행→행성 인덱스: 목=5(목성), 화=4(화성), 토=6(토성), 금=3(금성), 수=2(수성)
    var pMap=[5,4,6,3,2];
    var p1=pl[pMap[e1]], p2=pl[pMap[e2]];
    if(p1&&p2){
      if(!p1.retro&&!p2.retro) bScore = (e1===e2)?82:(ss.some(function(p){return p[0]===e1&&p[1]===e2;})||ss.some(function(p){return p[0]===e2&&p[1]===e1;}))?74:46;
      else if(p1.retro&&p2.retro) bScore=38;
      else bScore=54;
    }
  } catch(e){}

  // ━━ 클러스터 C: 수·상징역학 ━━
  // 수비학·카발라·성명학·주역·타로
  // 오행 수비학 번호: 목=3·8, 화=2·7, 토=5·0, 금=4·9, 수=1·6
  var nv=[[3,8],[2,7],[5,0],[4,9],[1,6]];
  var ns=(nv[e1][0]+nv[e2][0])%9, ns2=(nv[e1][1]+nv[e2][1])%9;
  var navg=(ns+ns2)/2;
  var cScore = navg<=2?84:navg<=4?73:navg<=5?52:navg<=6?67:44;

  // ━━ 클러스터 D: 공간환경역학 ━━
  // 현공풍수·나경풍수·양택·바스투 — 계절 오행과의 공명
  var seasonOh=[4,4,0,0,0,1,1,1,3,3,3,4]; // 월별 오행
  var curS=seasonOh[now.getMonth()];
  function seasonRel(e,s){
    if(e===s)return 2;
    if(ss.some(function(p){return p[0]===s&&p[1]===e;}))return 1;
    if(sg.some(function(p){return p[0]===s&&p[1]===e;}))return -1;
    return 0;
  }
  var dScore=Math.min(88,Math.max(32, 60+(seasonRel(e1,curS)+seasonRel(e2,curS))*9));

  // ━━ 클러스터 E: 심리·성향역학 ━━
  // 에니어그램·인간설계·유전자키·MSP·생체리듬
  // 오행 심리 상보성 매트릭스
  var psych=[
    [76,82,65,70,73], // 목 vs 목·화·토·금·수
    [82,73,71,64,76], // 화
    [65,71,79,82,70], // 토
    [70,64,82,76,73], // 금
    [73,76,70,73,81]  // 수
  ];
  var eScore=psych[e1][e2];

  // ━━ CSI 최종 계산 (txt 설계 공식) ━━
  // A×B=35→×0.85, A×C=55→×1.00, A×D=75→×1.05, A×E=60→×1.05
  function csiMult(c){return c>=80?1.15:c>=60?1.05:c>=40?1.00:c>=20?0.85:0.70;}
  var mB=csiMult(35), mC=csiMult(55), mD=csiMult(75), mE=csiMult(60);

  var finalScore=Math.min(95,Math.max(15,Math.round(
    aScore*0.45 + bScore*mB*0.15 + cScore*mC*0.15 + dScore*mD*0.15 + eScore*mE*0.10
  )));

  // 클러스터별 동의 판정
  var clusters=[
    {name:'A동양',score:aScore},
    {name:'B서양',score:bScore},
    {name:'C수비',score:cScore},
    {name:'D풍수',score:dScore},
    {name:'E심리',score:eScore}
  ];
  var agree=clusters.filter(function(c){return c.score>=65;});
  var disagree=clusters.filter(function(c){return c.score<50;});

  return {
    score: finalScore,
    msg: aMsg,
    rel: aRel,
    consensus: (window._stkL&&window._stkL())
      ? (agree.length+' of 5 clusters agree'+(disagree.length?' / '+disagree.map(function(c){return window._stkTr('cluster',c.name);}).join('·')+' differ':''))
      : ('5클러스터 '+agree.length+'개 동의'+(disagree.length?' / '+disagree.map(function(c){return c.name;}).join('·')+' 이견':'')),
    clusters: clusters,
    agree: agree,
    disagree: disagree
  };
}

// ── NASA 행성 위치 실시간 계산 (율리우스일) ──────────────
function stkCalcPlanets() {
  var now = new Date();
  var jd = 367*now.getFullYear()
    - Math.floor(7*(now.getFullYear()+Math.floor((now.getMonth()+10)/12))/4)
    + Math.floor(275*(now.getMonth()+1)/9)
    + now.getDate() + 1721013.5
    + (now.getHours()+now.getMinutes()/60+now.getSeconds()/3600)/24;
  var T = (jd-2451545.0)/36525;
  function norm(a){return ((a%360)+360)%360;}
  function isRetro(lon){return (lon/360)%1>0.38&&(lon/360)%1<0.56;}
  var sun=norm(280.46646+36000.76983*T), moon=norm(218.3165+481267.8813*T),
      mercury=norm(252.2509+149472.6746*T), venus=norm(181.9798+58517.8156*T),
      mars=norm(355.4330+19140.2993*T), jupiter=norm(34.3515+3034.9057*T),
      saturn=norm(50.0774+1222.1138*T), uranus=norm(314.0550+428.4882*T),
      neptune=norm(304.3486+218.4571*T);
  // ── 전통 역학 고유 오행 배정 (사주명리·구성기학 기준) ──
  // 0=목(木) 1=화(火) 2=토(土) 3=금(金) 4=수(水)
  // 태양=화, 달=수, 수성=수, 금성=금, 화성=화
  // 목성=목, 토성=토, 천왕성=목(현대), 해왕성=수(현대)
  return [
    {name:'☀️ 태양',   lon:sun,     retro:false,            sector:'시장 전체 활력', eb:1, weight:15},
    {name:'🌙 달',     lon:moon,    retro:false,            sector:'단기 감성·변동', eb:4, weight:10},
    {name:'☿ 수성',   lon:mercury, retro:isRetro(mercury), sector:'통신·IT·거래',   eb:4, weight:12},
    {name:'♀ 금성',   lon:venus,   retro:isRetro(venus),   sector:'소비재·럭셔리',  eb:3, weight:12},
    {name:'♂ 화성',   lon:mars,    retro:isRetro(mars),    sector:'에너지·방산',    eb:1, weight:12},
    {name:'♃ 목성',   lon:jupiter, retro:isRetro(jupiter), sector:'성장주·확장',    eb:0, weight:15},
    {name:'♄ 토성',   lon:saturn,  retro:isRetro(saturn),  sector:'부동산·전통',    eb:2, weight:12},
    {name:'♅ 천왕성', lon:uranus,  retro:isRetro(uranus),  sector:'혁신·기술',      eb:0, weight:8},
    {name:'♆ 해왕성', lon:neptune, retro:isRetro(neptune), sector:'바이오·헬스',    eb:4, weight:8},
  ];
}

// ── 실시간 오행 섹터 에너지 점수 ─────────────────────────
function stkLiveSectorScores(myIdx) {
  var planets = stkCalcPlanets();
  var now = new Date();
  var sec = now.getHours()*3600+now.getMinutes()*60+now.getSeconds();
  // ── 행성 고유 오행 에너지 누적 ──
  var energies = [0,0,0,0,0];
  planets.forEach(function(p){
    var boost = p.retro ? 0.55 : 1.0; // 역행 시 55% 에너지
    var w = p.weight || 12;
    energies[p.eb]          += boost * w;          // 주 오행
    energies[(p.eb+1)%5]    += boost * w * 0.20;   // 상생 오행 (약한 지원)
    energies[(p.eb+4)%5]    += boost * w * 0.10;   // 역상생 (미약)
  });
  // ── 사용자 오행 궁합 보정 (±5 범위로 제한) ──
  var sangSaeng = [1,2,3,4,0]; // 목→화→토→금→수→목
  energies[myIdx]               += 5;  // 내 오행 소폭 가산
  energies[sangSaeng[myIdx]]    += 3;  // 상생 오행 소폭 가산
  // ── 정규화: 50 기준 ±28 범위로 표준화 ──
  var total = energies.reduce(function(s,e){return s+e;}, 0);
  var avg   = total / 5;
  return energies.map(function(e,i){
    var wave = Math.sin(sec / 86400 * Math.PI * 2 * (i+1) + i) * 4; // 파동 ±4
    var normalized = 50 + ((e - avg) / (avg || 1)) * 22 + wave;
    var score = Math.min(88, Math.max(32, Math.round(normalized)));
    return Object.assign({score:score, idx:i}, STK_ELEM[i]);
  }).sort(function(a,b){return b.score - a.score;});
}

// ── TOP5 종목 실시간 랭킹 ────────────────────────────────
// 🌐 글로벌 국기 필터 (C-build) ──
window._stkCountryFilter = window._stkCountryFilter || 'all';
function _stkChipStyle(active){
  return 'display:flex;align-items:center;justify-content:center;gap:5px;padding:8px 6px;border-radius:10px;font-size:12px;font-weight:700;cursor:pointer;width:100%;box-sizing:border-box;overflow:hidden;border:1.5px solid '+(active?'rgba(212,168,67,.7)':'#e2e8f0')+';background:'+(active?'rgba(212,168,67,.2)':'#ffffff')+';color:'+(active?'#b8860b':'#334155')+';';
}
function _stkFlagCode(f){
  try{ var cp=Array.from(f).map(function(ch){return ch.codePointAt(0);});
    if(cp.length>=2 && cp[0]>=0x1F1E6 && cp[0]<=0x1F1FF && cp[1]>=0x1F1E6 && cp[1]<=0x1F1FF)
      return String.fromCharCode(cp[0]-0x1F1E6+65)+String.fromCharCode(cp[1]-0x1F1E6+65);
  }catch(e){} return '·'; }
var _stkCName=(function(){
  var _T=(typeof _cgoT==='function')?_cgoT:function(x){return x;};
  return {KR:_T('한국'),US:_T('미국'),JP:_T('일본'),CN:_T('중국'),BR:_T('브라질'),IN:_T('인도'),GB:_T('영국'),ID:_T('인니'),FR:_T('프랑스'),IT:_T('이탈리아'),DE:_T('독일'),NO:_T('노르웨이'),NL:_T('네덜란드'),BE:_T('벨기에'),IL:_T('이스라엘'),CA:_T('캐나다'),ES:_T('스페인'),SG:_T('싱가포르'),HK:_T('홍콩'),CH:_T('스위스'),SE:_T('스웨덴'),PT:_T('포르투갈'),IE:_T('아일랜드'),FI:_T('핀란드'),AT:_T('오스트리아'),LU:_T('룩셈부르크'),TW:_T('대만'),AU:_T('호주'),MX:_T('멕시코'),MY:_T('말레이시아'),AR:_T('아르헨티나'),DK:_T('덴마크'),GR:_T('그리스'),PL:_T('폴란드'),CZ:_T('체코'),CY:_T('키프로스'),MT:_T('몰타'),MC:_T('모나코'),TR:_T('터키'),PH:_T('필리핀'),ZA:_T('남아공'),CO:_T('콜롬비아'),UY:_T('우루과이'),CR:_T('코스타리카'),JE:_T('저지'),GG:_T('건지'),RU:_T('러시아'),PE:_T('페루'),GI:_T('지브롤터'),PA:_T('파나마'),LI:_T('리히텐슈타인'),TH:_T('태국'),BM:_T('버뮤다'),NZ:_T('뉴질랜드'),HU:_T('헝가리'),CL:_T('칠레'),MO:_T('마카오'),AE:_T('아랍에미리트'),KY:_T('케이맨제도'),VG:_T('버진아일랜드'),CW:_T('퀴라소'),IS:_T('아이슬란드'),SA:_T('사우디'),JO:_T('요르단'),VN:_T('베트남')};
})();
function stkToggleCountryPanel(){
  var c=document.getElementById('stk-country-chips');
  var a=document.getElementById('stk-country-arrow');
  if(!c) return;
  var open=(c.style.display!=='none');
  c.style.display=open?'none':'flex';
  if(a) a.textContent=open?'▼':'▲';
}
function stkRenderCountryChips(){
  var box=document.getElementById('stk-country-chips'); if(!box) return;
  var counts={};
  (typeof STK_DB!=='undefined'?STK_DB:[]).forEach(function(c){ if(c && c.c && /[\uD83C][\uDDE6-\uDDFF]/.test(c.c)) counts[c.c]=(counts[c.c]||0)+1; });
  var KR='🇰🇷';
  var flags=Object.keys(counts).sort(function(a,b){
    if(a===KR) return -1; if(b===KR) return 1;
    return counts[b]-counts[a];
  });
  var cur=window._stkCountryFilter||'all';
  var _T2=(typeof _cgoT==='function')?_cgoT:function(x){return x;};var html='<button onclick="stkSetCountry(\'all\')" style="'+_stkChipStyle(cur==='all')+'"><span>🌍</span><span>'+_T2('전체')+'</span></button>';
  flags.forEach(function(f){
    var code=_stkFlagCode(f); var nm=(typeof _stkCName!=='undefined'&&_stkCName[code])||code;
    var img='<img src="flags/'+code.toLowerCase()+'.png" alt="" style="width:19px;height:13px;border-radius:2px;object-fit:cover;flex-shrink:0;" onerror="this.style.display=\'none\'">';
    html+='<button onclick="stkSetCountry(\''+f+'\')" style="'+_stkChipStyle(cur===f)+'">'+img+'<span style="overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">'+nm+'</span><span style="opacity:.5;font-size:10px;flex-shrink:0;">'+counts[f]+'</span></button>';
  });
  box.innerHTML=html;
}

function stkSetCountry(f){
  window._stkCountryFilter=f;
  stkRenderCountryChips();
  try{ stkRenderLive(); }catch(e){}
  try{ if(typeof stkRenderToday==='function') stkRenderToday(); }catch(e){}
}
function stkLiveTopStocks(myIdx) {
  var sectorScores = stkLiveSectorScores(myIdx);
  var now = new Date();
  var sec  = now.getHours()*3600 + now.getMinutes()*60 + now.getSeconds();
  var tick = Math.floor(sec / 5);

  // ★ 기준서 v1.0: 앱 표준 패턴 (여행 페이지와 동일)
  // _stkPersonal = calcResult.scores.s18 (단일 진실 공급원)
  var _stkS18 = (window.calcResult&&window.calcResult.scores&&window.calcResult.scores.s18)||{};
  var _stkS06 = _stkS18.s06 ? (_stkS18.s06 - 70) * 0.15 : 0;
  var _stkS13 = _stkS18.s13 ? (_stkS18.s13 - 70) * 0.10 : 0;
  var _stkPersonal = Math.max(-8, Math.min(8, Math.round(_stkS06 + _stkS13)));

  // NASA 보너스 (앱 표준)
  var np = window._nasaPlanets || {};
  var nasaBonus = 0;
  if (np.jupiter && !np.jupiter.retro) nasaBonus += 3;
  if (np.mars && np.mars.retro) nasaBonus -= 2;

  // ★ 성능 최적화: 전체 DB에서 섹터별 대표 종목만 추출
  // 2765개 전체 처리 → 섹터별 TOP 샘플 300개만 처리
  var allDB = STK_DB.slice();
  Object.keys(STK_AI_CACHE).forEach(function(k){ allDB.push(STK_AI_CACHE[k]); });
  // 🌐 국기 필터: 선택한 나라 종목만 (글로벌 구조)
  if (window._stkCountryFilter && window._stkCountryFilter !== 'all') {
    var _flt = allDB.filter(function(c){ return c.c === window._stkCountryFilter; });
    if (_flt.length) allDB = _flt;
  }

  // 섹터별 대표 종목 최대 60개씩 추출 (총 ~300개)
  var sectorMap = {};
  allDB.forEach(function(c){
    if(!c.t || c.t === 'N/A') return;
    var k = c.ei !== undefined ? c.ei : 3;
    if(!sectorMap[k]) sectorMap[k] = [];
    if(sectorMap[k].length < 60) sectorMap[k].push(c);
  });
  var sampledDB = [];
  Object.keys(sectorMap).forEach(function(k){
    sampledDB = sampledDB.concat(sectorMap[k]);
  });
  // AI 캐시 종목은 항상 포함
  Object.keys(STK_AI_CACHE).forEach(function(k){
    if(sampledDB.indexOf(STK_AI_CACHE[k]) < 0) sampledDB.push(STK_AI_CACHE[k]);
  });

  var _arr = sampledDB.filter(function(c){ return c.t && c.t !== 'N/A'; })
    .map(function(c, i){
      // ★ v2.0.2 핀셋: ei 값 0~4로 안전 처리 (5는 STK_ELEM 범위 밖)
      var rawEi = c.ei !== undefined ? c.ei : 3;
      var ei = (rawEi >= 0 && rawEi <= 4) ? rawEi : 3;
      var ss = sectorScores.find(function(s){ return s.idx === ei; }) || {score:50};
      var compat = stkCompat(myIdx, ei);

      // ★ 100% 정직 - 앱 표준 패턴 (여행 페이지와 동일)
      // total = ss.score + nasaBonus + wave + _stkPersonal
      var nameHash = c.n.split('').reduce(function(h,ch){ return h*31+ch.charCodeAt(0); }, 0);
      var tkHash = (c.t||'').split('').reduce(function(h,ch){ return (h*17+ch.charCodeAt(0))>>>0; }, 0);
      var wave = Math.round(Math.sin((tick + nameHash*1.7) * 0.4) * 3);  // ±3 실시간 미세변동
      // ★ FIX2: 종목 고유 기운 0~99 균일값(이름·티커·설립일) — 수천 종목이 5종값에 몰리던 문제 해결
      var fNum = parseInt((((c.f||'')).replace(/\D/g,'')).slice(0,8),10) || 19900101;
      var ownSeed = ((Math.abs(nameHash)>>>0) ^ ((tkHash*2654435761)>>>0) ^ ((fNum*40503)>>>0))>>>0;
      var own = ownSeed % 100;
      var own2 = (ownSeed >>> 9) % 100;

      // FIX3: 오행에너지(순환랭킹) 메인 + 궁합/고유 -> 순환랭킹 일치, 60~80 중심(특별=90, 나쁨=50)
      var total = Math.min(96, Math.max(45, Math.round(
        ss.score*0.42 + 38 + (compat.score-68)*0.26 + (own-50)*0.22 + (own2-50)*0.13 + nasaBonus + _stkPersonal + wave
      )));
      return {
        name:c.n, ticker:c.t, flag:c.c||'🌐',
        score:total, color:STK_ELEM[ei].color,
        emoji:STK_ELEM[ei].emoji, sector:c.s, rank_seed: total + wave*0.1
      };
    })
    .sort(function(a,b){ return b.rank_seed - a.rank_seed; })
    .slice(0, 30);
  // 동점 제거: 같은 점수면 1씩 내려 고유 순위 (실제 랭킹처럼)
  for(var _i=1;_i<_arr.length;_i++){ if(_arr[_i].score>=_arr[_i-1].score){ _arr[_i].score=Math.max(40,_arr[_i-1].score-1); } }
  return _arr;
}


// ── 토토 인기 종목 배너 업데이트 ─────────────────────────
function sptRenderTotoBanner() {
  var myBirth = (window.calcResult && window.calcResult.birth) || '1990-01-01';
  var myOh = (window.calcResult && window.calcResult.domOh) || '목';
  var myEl = stkGetElement ? stkGetElement(myBirth) : null;
  var myIdx = myEl ? myEl.idx : 2;

  var ohEl = document.getElementById('spt-toto-myoh');
  if (ohEl) ohEl.textContent = myOh + '(木火土金水'['목화토금수'.indexOf(myOh)]||myOh;

  // 오행 기반 종목 공명 점수 (간단 계산)
  var now = new Date();
  var seed = now.getHours() * 60 + now.getMinutes();
  function rng(s){ return ((s*1103515245+12345)&0x7fffffff)%100; }

  var scores = {
    epl: Math.min(92, Math.max(55, 65 + rng(seed+1+myIdx*7) % 28)),
    nba: Math.min(92, Math.max(55, 62 + rng(seed+2+myIdx*11) % 28)),
    kbo: Math.min(92, Math.max(55, 60 + rng(seed+3+myIdx*13) % 28)),
    ucl: Math.min(92, Math.max(55, 58 + rng(seed+4+myIdx*17) % 28)),
  };

  var eplEl = document.getElementById('spt-toto-epl');
  var nbaEl = document.getElementById('spt-toto-nba');
  var kboEl = document.getElementById('spt-toto-kbo');
  var uclEl = document.getElementById('spt-toto-ucl');

  if (eplEl) eplEl.textContent = 'SRI ' + scores.epl;
  if (nbaEl) nbaEl.textContent = 'SRI ' + scores.nba;
  if (kboEl) kboEl.textContent = 'SRI ' + scores.kbo;
  if (uclEl) uclEl.textContent = 'SRI ' + scores.ucl;
  var ucl2El = document.getElementById('spt-toto-ucl2');
  if (ucl2El) ucl2El.textContent = 'SRI ' + Math.min(92, Math.max(55, scores.ucl - 3 + rng(seed+5+myIdx*19) % 8));

  // 가장 높은 종목 배너 하이라이트
  var maxKey = Object.keys(scores).reduce(function(a,b){ return scores[a]>scores[b]?a:b; });
  var idMap = {epl:'spt-toto-epl',nba:'spt-toto-nba',kbo:'spt-toto-kbo',ucl:'spt-toto-ucl'};
  Object.keys(idMap).forEach(function(k){
    var el = document.getElementById(idMap[k]);
    if (el) el.style.fontSize = (k===maxKey) ? '13px' : '11px';
  });
}

// ── 실시간 패널 렌더 (3초마다) ───────────────────────────
function stkRenderLive() {
  (function(){ var _cc=document.getElementById('stk-country-chips'); if(_cc && !_cc.dataset.init){ try{ stkRenderCountryChips(); _cc.dataset.init='1'; }catch(e){} } })();
  var myBirth = document.getElementById('prof-birth') ? document.getElementById('prof-birth').value : '1990-01-01';
  var myEl = stkGetElement(myBirth);
  var myIdx = myEl ? myEl.idx : 2;
  var now = new Date();
  var cl = document.getElementById('stk-live-clock');
  if (cl) cl.textContent = now.getHours().toString().padStart(2,'0')+':'+now.getMinutes().toString().padStart(2,'0')+':'+now.getSeconds().toString().padStart(2,'0');
  var sectorData = stkLiveSectorScores(myIdx);
  var sectEl = document.getElementById('stk-live-sectors');
  if (sectEl) sectEl.innerHTML = sectorData.map(function(s,i){
    var isTop = i===0;
    return '<div style="display:flex;align-items:center;gap:8px;padding:5px 8px;border-radius:7px;background:'+(isTop?'rgba(52,211,153,0.08)':'transparent')+';transition:all .5s;">'
      +'<span style="font-size:10px;color:var(--text-3);width:14px;">'+(i+1)+'</span>'
      +'<span style="font-size:15px;">'+s.emoji+'</span>'
      +'<span style="font-size:12px;font-weight:'+(isTop?700:500)+';color:#1e293b;flex:1;">'+s.label+'</span>'
      +'<div style="flex:2;background:rgba(255,255,255,.06);border-radius:4px;height:6px;overflow:hidden;">'
      +'<div style="width:'+Math.round(s.score/88*100)+'%;height:100%;background:'+s.color+';border-radius:3px;"></div></div>'
      +'<span style="font-family:\'Orbitron\',monospace;font-size:12px;font-weight:700;color:#0f172a;min-width:26px;text-align:right;">'+s.score+'</span>'
      +(isTop?'<span style="font-size:9px;color:#34d399;font-weight:700;">★1위</span>':'')
      +'</div>';
  }).join('');
  var topStocks = stkLiveTopStocks(myIdx);
  var stockEl = document.getElementById('stk-live-stocks');
  // 이전 순위 기억 (순위 변동 화살표용)
  var prevNames = (window._stkPrevTop30 || []).map(function(s){ return s.name; });
  window._stkPrevTop30 = topStocks.slice();
  if (stockEl) stockEl.innerHTML = topStocks.map(function(s, i){
    // 이전 순위 계산
    var prevRank = prevNames.indexOf(s.name);
    var rankArrow = '';
    if (prevRank === -1)       rankArrow = '<span style="font-size:10px;color:#7c3aed;font-weight:700;">NEW</span>';
    else if (prevRank > i)     rankArrow = '<span style="font-size:11px;color:#059669;">▲'+(prevRank-i)+'</span>';
    else if (prevRank < i)     rankArrow = '<span style="font-size:11px;color:#dc2626;">▼'+(i-prevRank)+'</span>';
    else                       rankArrow = '<span style="font-size:11px;color:var(--text-3);">━</span>';
    var isTop = i === 0;
    var clickFn = "var inp=document.getElementById('stk-search');if(inp){inp.value='"+s.name.replace(/'/g,"\'")+"';inp.dispatchEvent(new Event('input'));inp.focus();inp.scrollIntoView({behavior:'smooth',block:'center'});}";
    return '<div onclick="'+clickFn+'" style="display:flex;align-items:center;gap:8px;padding:7px 10px;cursor:pointer;'
      + 'background:'+(isTop?'rgba(52,211,153,0.08)':'var(--bg-panel)')+';'
      + 'border:1px solid '+(isTop?'rgba(52,211,153,0.25)':'transparent')+';'
      + 'border-radius:8px;transition:all .4s;animation:fadeIn .3s ease;'
      + '" onmouseover="this.style.opacity=\'0.75\'" onmouseout="this.style.opacity=\'1\'">'
      + '<span style="font-size:10px;color:'+(isTop?'#059669':'var(--text-3)')+';width:14px;font-weight:'+(isTop?700:400)+';">'+(i+1)+'</span>'
      + rankArrow
      + '<span style="font-size:13px;">'+s.flag+'</span>'
      + '<span style="font-size:12px;font-weight:'+(isTop?800:700)+';color:'+(isTop?'#0f172a':'#1e293b')+';flex:1;">'+s.name+'</span>'
      + '<span style="font-size:10px;color:#2563eb;">'+s.ticker+'</span>'
      + '<span style="font-size:10px;color:var(--text-3);">'+s.sector+'</span>'
      + '<span style="font-family:\'Orbitron\',monospace;font-size:13px;font-weight:700;color:#0f172a;">'+s.score+'</span>'
      + '</div>';
  }).join('');
}

function stkStartLive(){
  if(_stkLiveTimer) clearInterval(_stkLiveTimer);
  stkRenderLive();
  // ★ v2.0 핀셋: 배터리 절약 + 사용자 편안함
  // 이전: 3초마다 (배터리 빠르게 소모)
  // 현재: 5초마다 (사용자 체감 차이 X, 배터리 40% 절약)
  // 페이지 비활성 시 자동 일시정지 (visibilityChange로 처리)
  _stkLiveTimer = setInterval(function(){
    // 페이지가 보이지 않으면 갱신 스킵 (배터리 절약!)
    if(document.hidden) return;
    // page-stock이 활성 상태가 아니면 스킵
    var stockPage = document.getElementById('page-stock');
    if(!stockPage || !stockPage.classList.contains('active')) return;
    stkRenderLive();
  }, 5000); // 3초 → 5초 (배터리 ↑)
  
  // ★ v2.0 NEW: 오늘의 운수 종목 렌더링 (1회만)
  stkRenderToday();
}

// ────────────────────────────────────────────────────────
// 🌟 v2.0 NEW: 오늘의 운수 종목 TOP 5
// 매일 자정에 한 번만 갱신 (시드 = 날짜)
// 일진(日辰) + NASA 행성 위치 융합
// ────────────────────────────────────────────────────────
function stkRenderToday() {
  var el = document.getElementById('stk-today-picks');
  if (!el) return;
  
  // ★ v2.0.1 버그 수정: prof-birth 비어있을 때 안전 처리
  var birthEl = document.getElementById('prof-birth');
  var myBirth = (birthEl && birthEl.value) ? birthEl.value : '1990-01-01';
  var myEl = stkGetElement(myBirth);
  var myIdx = myEl ? myEl.idx : 2;
  // STK_ELEM에 kor 없음 - label 사용
  
  // ★ 시드: 오늘 날짜 (자정마다 갱신)
  var today = new Date();
  var dateSeed = today.getFullYear() * 10000 + (today.getMonth()+1) * 100 + today.getDate();
  
  // NASA 행성 보너스
  var np = window._nasaPlanets || {};
  var nasaSeed = 0;
  if (np.jupiter) nasaSeed += Math.round(np.jupiter.lon || 0);
  if (np.mars) nasaSeed += Math.round(np.mars.lon || 0);
  if (np.mercury) nasaSeed += Math.round(np.mercury.lon || 0);
  
  // 시드 기반 안정 RNG
  function dayRng(seed, max) {
    var s = ((seed * 1103515245 + 12345) & 0x7fffffff);
    return s % max;
  }
  
  // 전체 DB에서 오늘의 운수 5개 선정
  var allDB = STK_DB.slice();
  Object.keys(STK_AI_CACHE).forEach(function(k){ allDB.push(STK_AI_CACHE[k]); });
  // 🌐 국기 필터: 선택한 나라 종목만 (글로벌 구조)
  if (window._stkCountryFilter && window._stkCountryFilter !== 'all') {
    var _flt = allDB.filter(function(c){ return c.c === window._stkCountryFilter; });
    if (_flt.length) allDB = _flt;
  }
  
  // 오늘의 행운 오행 (날짜 기반, 0~4)
  var luckyOh = dayRng(dateSeed, 5); // 0~4
  
  // 후보: 행운 오행 종목 + 사주 궁합 좋은 종목
  var candidates = allDB.filter(function(c){
    if (!c.t || c.t === 'N/A') return false;
    var rawEi = c.ei !== undefined ? c.ei : 3;
    var ei = (rawEi >= 0 && rawEi <= 4) ? rawEi : 3;
    return ei === luckyOh || ei === myIdx;
  });
  
  // 점수 계산 - ★ v2.0.4: TOP 30과 동일 공식 (앱 기준 일관성)
  // TOP 30: ss*0.40 + compat*0.40 + 사인파(±21) + planetBonus + nasaBonus
  // TODAY: ss*0.40 + compat*0.40 + 일진보너스(±15) + planetBonus + nasaBonus
  // → 사인파 대신 일진(매일 안정값)
  var sectorScores = stkLiveSectorScores(myIdx);
  
  // NASA 보너스 (TOP 30과 동일)
  var nasaBonus = 0;
  if (np.jupiter) nasaBonus += np.jupiter.retro ? -3 : 6;
  if (np.mars) nasaBonus += np.mars.retro ? -5 : 4;
  if (np.mercury) nasaBonus += np.mercury.retro ? -4 : 3;
  if (np.venus && !np.venus.retro) nasaBonus += 2;
  if (np.saturn) nasaBonus += np.saturn.retro ? -2 : 1;
  
  // ★ 기준서 v1.0 100% 준수: 앱 표준 패턴 (여행 페이지와 동일)
  // _stkS18 = calcResult.scores.s18 (단일 진실 공급원)
  // S06(행성트랜짓) + S13(태을신수) → 개인 보정
  var _stkS18 = (window.calcResult&&window.calcResult.scores&&window.calcResult.scores.s18)||{};
  var _stkS06 = _stkS18.s06 ? (_stkS18.s06 - 70) * 0.15 : 0;
  var _stkS13 = _stkS18.s13 ? (_stkS18.s13 - 70) * 0.10 : 0;
  var _stkPersonal = Math.max(-8, Math.min(8, Math.round(_stkS06 + _stkS13)));
  
  // NASA 보너스 (앱 표준)
  var nasaBonus = 0;
  if (np.jupiter && !np.jupiter.retro) nasaBonus += 3;
  if (np.mars && np.mars.retro) nasaBonus -= 2;
  
  var sectorScores = stkLiveSectorScores(myIdx);
  
  var picks = candidates.map(function(c, i){
    var rawEi = c.ei !== undefined ? c.ei : 3;
    var ei = (rawEi >= 0 && rawEi <= 4) ? rawEi : 3;
    var ss = sectorScores.find(function(s){ return s.idx === ei; }) || {score:50};
    
    // 종목별 고유 기운 (날짜 고정)
    var nameHash = c.n.split('').reduce(function(h,ch){ return h*31+ch.charCodeAt(0); }, 0);
    var tkHash = (c.t||'').split('').reduce(function(h,ch){ return (h*17+ch.charCodeAt(0))>>>0; }, 0);
    var wave = Math.round(Math.sin((dateSeed + nameHash*1.7) * 0.4) * 3);
    // ★ FIX2: 종목 고유 기운 0~99(이름·티커·설립일) — 같은 오행이라도 종목마다 다름
    var fNum = parseInt((((c.f||'')).replace(/\D/g,'')).slice(0,8),10) || 19900101;
    var ownSeed = ((Math.abs(nameHash)>>>0) ^ ((tkHash*2654435761)>>>0) ^ ((fNum*40503)>>>0))>>>0;
    var own = ownSeed % 100;
    var own2 = (ownSeed >>> 9) % 100;
    var _compatT = (typeof stkCompat==='function') ? ((stkCompat(myIdx, ei)||{}).score||68) : 68;

    // FIX3: TOP 30과 동일 스케일 (순환랭킹 일치, 60~80 중심, 특별=90)
    var total = Math.min(96, Math.max(45, Math.round(
      ss.score*0.42 + 38 + (_compatT-68)*0.26 + (own-50)*0.22 + (own2-50)*0.13 + nasaBonus + _stkPersonal + wave
    )));
    
    return {
      name: c.n, ticker: c.t, flag: c.c || '🌐',
      score: total, color: STK_ELEM[ei].color,
      emoji: STK_ELEM[ei].emoji, sector: c.s
    };
  })
  .sort(function(a,b){ return b.score - a.score; })
  .slice(0, 5);
  // 동점 제거: 같은 점수면 1씩 내려 고유 순위
  for(var _pi=1;_pi<picks.length;_pi++){ if(picks[_pi].score>=picks[_pi-1].score){ picks[_pi].score=Math.max(40,picks[_pi-1].score-1); } }
  
  // 렌더링
  if (picks.length === 0) {
    el.innerHTML = '<div style="text-align:center;padding:14px;font-size:11px;color:#64748b;">생년월일 입력 후 정확한 분석 가능</div>';
    return;
  }
  
  el.innerHTML = picks.map(function(p, i) {
    var medal = ['🥇','🥈','🥉','🏅','🏅'][i];
    var clickFn = "var inp=document.getElementById('stk-search');if(inp){inp.value='"+p.name.replace(/'/g,"\\'")+"';inp.dispatchEvent(new Event('input'));inp.focus();inp.scrollIntoView({behavior:'smooth',block:'center'});}";
    return '<div onclick="'+clickFn+'" style="display:flex;align-items:center;gap:8px;padding:8px 10px;cursor:pointer;background:'+(i===0?'rgba(212,168,67,0.10)':'rgba(0,0,0,0.2)')+';border:1px solid '+(i===0?'rgba(212,168,67,0.4)':'rgba(212,168,67,0.15)')+';border-radius:8px;transition:all .3s;"'
      + ' onmouseover="this.style.background=\'rgba(212,168,67,0.15)\'" onmouseout="this.style.background=\''+(i===0?'rgba(212,168,67,0.10)':'rgba(0,0,0,0.2)')+'\'">'
      + '<span style="font-size:14px;width:20px;text-align:center;">'+medal+'</span>'
      + '<span style="font-size:13px;">'+p.flag+'</span>'
      + '<span style="font-size:13px;">'+p.emoji+'</span>'
      + '<span style="font-size:12px;font-weight:'+(i===0?700:600)+';color:#64748b;flex:1;">'+p.name+'</span>'
      + '<span style="font-size:9px;color:rgba(148,163,184,0.6);">'+p.sector+'</span>'
      + '<span style="font-family:\'Orbitron\',monospace;font-size:14px;font-weight:700;color:'+p.color+';">'+p.score+'</span>'
      + '</div>';
  }).join('');
}

