function stkAlgoAnalysis(coIdx, myIdx) {
  var now = new Date();
  var sec = now.getHours()*3600+now.getMinutes()*60+now.getSeconds();
  var compat = stkCompat(myIdx, coIdx);
  var algos = Object.keys(STK_ALGO_DATA);
  return algos.map(function(name, i){
    var score = 40+((sec+compat.score+i*17+coIdx*7)%50);
    var ti = (Math.floor(sec/300+i+coIdx))%4;
    var trends=['📈 상승','➡️ 중립','📉 조정','🔄 전환'];
    var colors=['#34d399','#94a3b8','#f87171','#fbbf24'];
    return {name:name, score:Math.min(95,score), trend:trends[ti], color:colors[ti]};
  });
}

// ── 모달 열기 ─────────────────────────────────────────────
function stkOpenModal(name, score, trend, trendColor) {
  var d = STK_ALGO_DATA[name];
  if (!d) return;
  if(window._LANG&&window._LANG!=='ko'&&typeof STK_ALGO_DATA_EN!=='undefined'&&STK_ALGO_DATA_EN[name]) d=STK_ALGO_DATA_EN[name];

  // 현재 분석된 종목 정보 가져오기
  var coName = stkSelected ? stkSelected.n : '종목';
  var coEl   = stkSelected ? STK_ELEM[stkSelected.ei||3] : STK_ELEM[3];
  var myBirth = document.getElementById('prof-birth') ? document.getElementById('prof-birth').value : '1990-01-01';
  var myEl   = stkGetElement(myBirth);
  var compat = stkSelected ? stkCompat(myEl?myEl.idx:2, stkSelected.ei||3) : {score:70};

  // 동적 에너지 해석 생성
  var trendText = trend.replace(/📈|➡️|📉|🔄/g,'').trim();
  var nowTexts = {
    '상승': coName+'의 '+name.replace(/[^\w가-힣\s]/g,'')+' 에너지가 <b style="color:#34d399;">상승 국면</b>에 있습니다. '+coEl.emoji+' '+coEl.label+' 오행 에너지가 강하게 활성화되어 있으며, 나의 오행과의 궁합('+compat.score+'점)이 현재 에너지를 증폭시키고 있습니다.',
    '중립': coName+'의 '+name.replace(/[^\w가-힣\s]/g,'')+' 에너지는 <b style="color:#94a3b8;">중립 흐름</b>입니다. '+coEl.emoji+' '+coEl.label+' 에너지가 균형을 이루고 있어 급격한 변동보다는 안정적인 흐름이 예상됩니다. 관망하며 다음 에너지 방향을 확인하세요.',
    '조정': coName+'의 '+name.replace(/[^\w가-힣\s]/g,'')+' 에너지가 <b style="color:#f87171;">조정 국면</b>에 진입해 있습니다. '+coEl.emoji+' '+coEl.label+' 에너지가 일시적으로 수렴 중입니다. 음극필양 원리에 따라 이 조정이 완료되면 다음 상승 에너지가 준비됩니다.',
    '전환': coName+'의 '+name.replace(/[^\w가-힣\s]/g,'')+' 에너지가 <b style="color:#b8860b;">전환점</b>에 있습니다. '+coEl.emoji+' '+coEl.label+' 오행 에너지의 방향이 바뀌는 시점으로, 새로운 사이클의 시작 또는 기존 추세의 마무리 구간입니다. 방향 확인 후 결정을 권장합니다.',
  };

  if(window._LANG&&window._LANG!=='ko'){
    var _nnm=name.replace(/[^\w가-힣\s]/g,'').trim();
    var _elL=({'목':'Wood','화':'Fire','토':'Earth','금':'Metal','수':'Water'})[coEl.label]||coEl.label;
    nowTexts={
      '상승': coName+'\u2019s '+_nnm+' energy is in a <b style="color:#34d399;">rising phase</b>. The '+coEl.emoji+' '+_elL+' element energy is strongly active, amplified by its fit with your element ('+compat.score+' pts).',
      '중립': coName+'\u2019s '+_nnm+' energy is in a <b style="color:#94a3b8;">neutral flow</b>. The '+coEl.emoji+' '+_elL+' energy is balanced, so expect a steady flow. Watch for the next direction.',
      '조정': coName+'\u2019s '+_nnm+' energy has entered a <b style="color:#f87171;">correction phase</b>. The '+coEl.emoji+' '+_elL+' energy is temporarily converging; the next rise prepares once it completes.',
      '전환': coName+'\u2019s '+_nnm+' energy is at a <b style="color:#b8860b;">turning point</b>. The '+coEl.emoji+' '+_elL+' energy is changing direction. Confirm direction before deciding.'
    };
  }
  // DOM 업데이트
  document.getElementById('m-icon').textContent = d.icon;
  /* ★2026-08-07 — name에 이모지가 붙어 있어 영어표에서 못 찾고 한국어로 떨어졌다. 먼저 떼고 찾는다. */
  var _bare = name.replace(/[☯️🌟♈🔢☁️🌙🏔️🔵🧿📿☽🌊⭕🎴🌀💫🕉️🔯]/gu,'').trim();
  document.getElementById('m-name').textContent =
    (window._LANG&&window._LANG!=='ko'&&(STK_ALGO_NAME_EN[name]||STK_ALGO_NAME_EN[_bare]))
      ? (STK_ALGO_NAME_EN[name]||STK_ALGO_NAME_EN[_bare]) : _bare;
  document.getElementById('m-origin').textContent = d.origin;
  document.getElementById('m-score').textContent = score;
  document.getElementById('m-score').style.color = trendColor;
  document.getElementById('m-trend').textContent = _cgoTV(trend,({'📈 상승':'📈 Rising','➡️ 중립':'➡️ Neutral','📉 조정':'📉 Correction','🔄 전환':'🔄 Turning'}[trend]||trend));
  document.getElementById('m-trend').style.color = trendColor;
  document.getElementById('m-bar').style.width = score+'%';
  document.getElementById('m-bar').style.background = 'linear-gradient(90deg,'+trendColor+','+trendColor+'88)';
  document.getElementById('m-summary').textContent = d.summary;
  document.getElementById('m-desc').textContent = d.desc;
  document.getElementById('m-stock').textContent = d.stock;
  document.getElementById('m-now').innerHTML = nowTexts[trendText] || nowTexts['중립'];
  document.getElementById('m-tip').textContent = d.tip;

  // 모달 표시
  var modal = document.getElementById('stk-algo-modal');
  modal.style.display = 'flex';
  setTimeout(function(){ modal.style.opacity='1'; }, 10);
  // ✅ 번역 트리거
  if (window._LANG && window._LANG !== 'ko') {
    setTimeout(function(){ _cgoTransPopup('stk-algo-modal'); }, 300);
  }
}

